window.EW=window.EW||{pages:{}};window.EW.pages["wiki-chronologie"]={"html":"<p>Les dates officiellement enseignées à Elderwood, et les autres dates connues.<\/p><h3 id=\"chronologie-d-elderwood\">Chronologie d'Elderwood<\/h3><p>Les dates officiellement enseignées à Elderwood.<\/p><div class=\"tbl-wrap\"><table class=\"doc-table\"><thead><tr><th scope=\"col\">Date<\/th><th scope=\"col\">Événement<\/th><\/tr><\/thead><tbody><tr><td>1298<\/td><td><strong>La découverte de la Source de Vehr<\/strong> : Falcon découvre une source d'eau capable de révéler la couleur de l'âme des Résonants (voir <a href=\"#/p/wiki-les-lieux--la-source\">La Source<\/a>).<\/td><\/tr><tr><td>1300<\/td><td><strong>Fondation d'Elderwood<\/strong> : Falcon, Aerwyn, Venatrix et Brumval fondent l'école.<\/td><\/tr><tr><td>1432<\/td><td><strong>La Sentence de Mireille<\/strong> : Gwendolyn Caerwyn applique une sanction controversée, un choix qui divise encore la maison Aerwyn.<\/td><\/tr><tr><td>1463<\/td><td><strong>La Flamme Ouverte<\/strong> : Elspeth Hearthbane organise le premier grand festival ouvert à toutes les entités magiques.<\/td><\/tr><tr><td>1863<\/td><td><strong>La codification du Razorball<\/strong> : Corvinus Valemont établit le règlement moderne du sport.<\/td><\/tr><tr><td>1944-1945<\/td><td><strong>Le Grand Confinement<\/strong> : Cassiopée Valemont rédige les décrets d'isolation du monde magique.<\/td><\/tr><\/tbody><\/table><\/div><h3 id=\"autres-dates-connues\">Autres dates connues<\/h3><div class=\"tbl-wrap\"><table class=\"doc-table\"><thead><tr><th scope=\"col\">Date<\/th><th scope=\"col\">Événement<\/th><th scope=\"col\">Voir<\/th><\/tr><\/thead><tbody><tr><td>Années 1330 (XIVe siècle)<\/td><td>La Crise des Archives : les Valemont, sous l'impulsion d'Aethelgard Valemont, sauvent les savoirs de l'école.<\/td><td><a href=\"#/p/wiki-familles-originelles--famille-valemont\">Famille Valemont<\/a><\/td><\/tr><tr><td>XVe siècle<\/td><td>Edgar Ravenscroft neutralise un immense Échoïde, base de la Méthode Ravenscroft.<\/td><td><a href=\"#/p/wiki-personnages\">Personnages illustres<\/a><\/td><\/tr><tr><td>1666<\/td><td>Grand Incendie de Londres : Bénédicte Hearthbane et plusieurs Brumval permettent d'évacuer les familles résonantes prises au piège.<\/td><td><a href=\"#/p/wiki-personnages\">Personnages illustres<\/a><\/td><\/tr><tr><td>1685<\/td><td>Loi sur la Pureté Botanique : le patriarche Thaddeus Belladorn simule sa propre mort plutôt que de livrer ses archives.<\/td><td><a href=\"#/p/wiki-familles-notables--famille-belladorn\">Famille Belladorn<\/a><\/td><\/tr><tr><td>1890<\/td><td>L'Incident de 1890 : Rowena Dravenholt désamorce une situation potentiellement embarrassante.<\/td><td><a href=\"#/p/wiki-familles-originelles--famille-dravenholt\">Famille Dravenholt<\/a><\/td><\/tr><tr><td>1890<\/td><td>L'Expédition de Shedwood, menée par Rowena Glenhart pendant quarante jours.<\/td><td><a href=\"#/p/wiki-personnages\">Personnages illustres<\/a><\/td><\/tr><tr><td>1896<\/td><td>Première Coupe du Monde de Razeball.<\/td><td>Razorball<\/td><\/tr><tr><td>1958<\/td><td>Baie de Lituya : Cadoc Caerwyn et trois autres Aerwyn maintiennent une barrière de protection pendant trois jours et trois nuits.<\/td><td><a href=\"#/p/wiki-personnages\">Personnages illustres<\/a><\/td><\/tr><tr><td>2026<\/td><td>Mort d'Arthurius Glenwood, directeur d'Elderwood ; son successeur sera révélé à la rentrée 2026.<\/td><td><a href=\"#/p/wiki-personnages\">Personnages illustres<\/a><\/td><\/tr><\/tbody><\/table><\/div>","toc":[{"id":"chronologie-d-elderwood","t":"Chronologie d'Elderwood","l":3},{"id":"autres-dates-connues","t":"Autres dates connues","l":3}]};
